/*!50003 CREATE*/ /*!50017 DEFINER=`sa`@`%`*/ /*!50003 TRIGGER utrigger_Rera_ProjectExtensionForm_EventRecord_INSERT
AFTER INSERT ON tbl_rera_project_extensionform_eventaction
FOR EACH ROW
BEGIN      
     DECLARE v_PromoterId BigInt; 
     Declare v_ProjectId BigInt;
     Declare v_ExtnProjectId BigInt;
     Declare v_ProjectDiaryNumber varchar(100); 
     Declare v_ExtensionFormDiaryNumber varchar(100);     
     Declare v_EventType int;   
       
       SET v_ProjectId=NEW.Related_Project_ID;         
       SET v_PromoterId=NEW.Related_Promoter_ID;
       SET v_ProjectDiaryNumber=NEW.Promoter_DiaryNumber;
       SET v_ExtensionFormDiaryNumber=NEW.Project_DiaryNumber;       
       SET v_EventType=NEW.EventAction_Type;
	   SET v_ExtnProjectId=0;

 -- In-Complete Application Details          
 If v_EventType = 150007   
 then      
    update tbl_rera_projectextensionform_regdiarynumber set IsDraft=0, IsDraftHelpDesk=0 where Promoter_ID=v_PromoterId and Project_ID=v_ProjectId and IsActive=1;
   
    update tbl_rera_project_applicationforextensionform set IsDraft=4, IsTemp=1 where Promoter_ID=v_PromoterId and Project_ID=v_ProjectId and IsActive=1 and IsDraft=5;
    update tbl_rera_project_payment_extensionforme set IsDraft=4 where ProjectPaymentRelated_ProjectRegistration_ID=v_ProjectId and IsActive=1 and IsDraft=5;
    -- select * from tbl_rera_project_extensionform_paymentgateway;
    
    -- ExtnProject Reminder Scheduler Updates
	CALL usp_insert_tbl_rera_project_extnform_reminderscheduler_emails(v_ProjectId, v_PromoterId, v_ExtnProjectId, v_ExtensionFormDiaryNumber, v_EventType);
	CALL usp_insert_tbl_rera_project_extnform_reminderscheduler_sms(v_ProjectId, v_PromoterId, v_ExtnProjectId, v_ExtensionFormDiaryNumber, v_EventType);
 end if;
 
 -- No Reply Found within 90 days from Promoter  
 If v_EventType = 150029  
 then
 	update tbl_rera_projectextensionform_regdiarynumber set IsDraft=1, IsDraftHelpDesk=1 where Promoter_ID=v_PromoterId and Project_ID=v_ProjectId and IsActive=1;
    
    update tbl_rera_project_applicationforextensionform set IsDraft=1, IsTemp=1 where Promoter_ID=v_PromoterId and Project_ID=v_ProjectId and IsActive=1 and IsDraft in (0,4,5);
    update tbl_rera_project_payment_extensionforme set IsDraft=1 where ProjectPaymentRelated_ProjectRegistration_ID=v_ProjectId and IsActive=1 and IsDraft in (0,4,5);
    
 end if;  
 
 -- Extension Form of Registered Project - LOCK
If ((v_EventType = 150017) or (v_EventType = 150020) or (v_EventType = 150021)) 
then 
   update tbl_rera_projectextensionform_regdiarynumber set IsDraftMember=1, IsDraftHelpDesk=1 where Promoter_ID=v_PromoterId and Project_ID=v_ProjectId and IsActive=1;
   
end if;
 
 
 END */;;
